from pathlib import Path
import argparse,json,hashlib,subprocess,sys
p=argparse.ArgumentParser();p.add_argument('--binding',required=True);p.add_argument('--partvtk',required=True);p.add_argument('--audit-worker',required=True);p.add_argument('--output-dir',required=True);a=p.parse_args();b=json.loads(Path(a.binding).read_text());out=Path(a.output_dir);out.mkdir(parents=True,exist_ok=False);f=b['files'];xml=Path(f['generated_xml']['path']);bi4=Path(f['generated_bi4']['path']);sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();assert sha(bi4)==f['generated_bi4']['sha256'];dst=out/'initial-all.csv';cmd=[a.partvtk,'-filedata',str(bi4),'-filexml',str(xml),'-threads:2','-savecsv',str(dst),'-onlytype:+all','-vars:-all,+idp,+vel,+rhop,+press,+type,+mk,+mass,+zone','-csvsep:1'];subprocess.run(cmd,cwd=out,check=True);csvs=[p for p in out.glob('*.csv') if not p.name.endswith('_stats.csv')];assert len(csvs)==1;f['official_particle_csv']={'path':str(csvs[0]),'sha256':sha(csvs[0])};runtime=out/'actual-producer-bound-placement-QA.json';runtime.write_text(json.dumps(b,indent=2)+'\n');r=subprocess.run([sys.executable,a.audit_worker,'--binding',str(runtime),'--output-dir',str(out/'placement')],check=False);(out/'registered-export-and-placement-producer.json').write_text(json.dumps({'official_export_command':cmd,'CSV':f['official_particle_csv'],'runtime_binding':{'path':str(runtime),'sha256':sha(runtime)},'placement_worker':{'path':a.audit_worker,'sha256':sha(a.audit_worker)},'placement_returncode':r.returncode,'input_BI4_SHA_unchanged':sha(bi4)==f['generated_bi4']['sha256']},indent=2)+'\n');raise SystemExit(r.returncode)
